import itertools,json,os
# A finite Boolean lattice sanity check of the complement-pullback mechanism:
# if f^{-1}(K_B)=K_A, the identical f pulls back complements.
checks=0
for n in range(1,5):
    U=set(range(n))
    for f in itertools.product(range(n),repeat=n):
        for mask in range(1<<n):
            KB={i for i in U if mask>>i&1}
            KA={i for i in U if f[i] in KB}
            assert U-KA=={i for i in U if f[i] in U-KB}
            checks+=1
os.makedirs('workspace',exist_ok=True)
result={'checks':checks,'statement':'finite preimage commutes with complement; no infinite theorem claimed'}
with open('workspace/agent2_pullback_checks.json','w') as f: json.dump(result,f,indent=2)
print(result)

